def steps(grid, start, goal):
    q = deque([(start, 0)])
    seen = set()
    while q:
        (r, c), d = q.popleft()
        if (r, c) == goal:
            return d
        seen.add((r, c))
        for nr, nc in ((r+1, c), (r-1, c), (r, c+1), (r, c-1)):
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 0 and (nr, nc) not in seen:
                q.append(((nr, nc), d + 1))
    return -1

