from functools import lru_cache

@lru_cache(maxsize=None)
def ways(i, j):
    if i == 0 or j == 0:
        return 1
    return ways(i - 1, j) + ways(i, j - 1)

import heapq

def merge_lists(lists):
    h = []
    for lst in lists:
        if lst:
            heapq.heappush(h, (lst.val, lst))
    out = []
    while h:
        val, node = heapq.heappop(h)
        out.append(val)
        if node.next:
            heapq.heappush(h, (node.next.val, node.next))
    return out
